import { IconLayoutList } from "@tabler/icons-react";

import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";

interface DisplayComponentProps {
	children: React.ReactNode;
}

export function DisplayComponent({
	children,
}: DisplayComponentProps): React.JSX.Element {
	return (
		<Popover>
			<PopoverTrigger asChild={true}>
				<button
					aria-label="Display options"
					className="flex h-8 items-center gap-1.5 rounded-md border border-input px-2 text-muted-foreground text-sm transition-colors hover:bg-muted hover:text-foreground"
					type="button"
				>
					<IconLayoutList className="size-4" />
					<span>Display</span>
				</button>
			</PopoverTrigger>
			<PopoverContent align="end" className="w-64 p-0" side="bottom">
				<div className="flex flex-col divide-y">{children}</div>
			</PopoverContent>
		</Popover>
	);
}

import type { TableFeatures } from "@adistack/data-explorer";
import { useDataExplorerContext } from "@adistack/data-explorer";
import { IconLayoutList } from "@tabler/icons-react";
import type { Column } from "@tanstack/react-table";

import { Checkbox } from "@/components/ui/checkbox";

export function DisplayColumnSelector(): React.JSX.Element {
	const { table } = useDataExplorerContext();

	const columns = table.getAllLeafColumns();

	return (
		<div className="p-3">
			<div className="mb-2 flex items-center gap-1.5 font-medium text-muted-foreground text-xs">
				<IconLayoutList className="size-3.5" />
				Columns
			</div>
			<div className="flex flex-col gap-1">
				{columns.map((column) => (
					<ColumnVisibilityRow column={column} key={column.id} />
				))}
			</div>
		</div>
	);
}

interface ColumnVisibilityRowProps {
	column: Column<TableFeatures, Record<string, unknown>>;
}

function ColumnVisibilityRow({
	column,
}: ColumnVisibilityRowProps): React.JSX.Element {
	const isVisible = column.getIsVisible();
	const meta = column.columnDef.meta;
	const Icon = meta?.icon as
		| React.ComponentType<{ className?: string }>
		| undefined;

	const toggle = (): void => {
		column.toggleVisibility(!isVisible);
	};

	const handleKeyDown = (e: React.KeyboardEvent): void => {
		if (e.key === "Enter" || e.key === " ") {
			e.preventDefault();
			toggle();
		}
	};

	const handleCheckedChange = (checked: boolean | "indeterminate"): void => {
		column.toggleVisibility(checked !== false);
	};

	return (
		// biome-ignore lint/a11y/useSemanticElements: ARIA checkbox wrapping a Radix Checkbox (button); native input not applicable
		<div
			aria-checked={isVisible}
			className="flex cursor-pointer items-center gap-2 rounded-sm px-1 py-0.5 text-sm hover:bg-muted"
			onClick={toggle}
			onKeyDown={handleKeyDown}
			role="checkbox"
			tabIndex={0}
		>
			<Checkbox
				checked={isVisible}
				onCheckedChange={handleCheckedChange}
				tabIndex={-1}
			/>
			{!!Icon && <Icon className="size-3.5 shrink-0 text-muted-foreground" />}
			<span>{meta?.displayName ?? column.id}</span>
		</div>
	);
}

import { useDataExplorerContext } from "@adistack/data-explorer";
import {
	IconArrowsSort,
	IconSortAscending,
	IconSortDescending,
} from "@tabler/icons-react";
import { useCallback } from "react";

import {
	Select,
	SelectContent,
	SelectGroup,
	SelectItem,
	SelectLabel,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";

export function SortingSelector(): React.JSX.Element {
	const { table } = useDataExplorerContext();

	const visibleColumns = table.getVisibleLeafColumns();
	const sorting = table.state.sorting;
	const current = sorting[0];
	const currentId = current?.id;
	const currentDesc = current?.desc ?? false;
	const isAscending = !currentDesc;

	const handleSortColumnChange = useCallback(
		(value: string) => {
			table.setSorting([{ desc: currentDesc, id: value }]);
		},
		[table, currentDesc],
	);

	const toggleSortDirection = useCallback(() => {
		if (!currentId) return;
		table.setSorting([{ desc: !currentDesc, id: currentId }]);
	}, [table, currentId, currentDesc]);

	return (
		<div className="p-3">
			<div className="mb-2 flex items-center gap-1.5 font-medium text-muted-foreground text-xs">
				<IconArrowsSort className="size-3.5" />
				Sort
			</div>
			<div className="flex items-center gap-2">
				<Select
					onValueChange={handleSortColumnChange}
					value={currentId ?? undefined}
				>
					<SelectTrigger className="h-8 flex-1" size="sm">
						<SelectValue />
					</SelectTrigger>
					<SelectContent>
						<SelectGroup>
							<SelectLabel>Column</SelectLabel>
							{visibleColumns.map((column) => {
								const meta = column.columnDef.meta;
								return (
									<SelectItem key={column.id} value={column.id}>
										{meta?.displayName ?? column.id}
									</SelectItem>
								);
							})}
						</SelectGroup>
					</SelectContent>
				</Select>
				<button
					aria-label={`Sort ${isAscending ? "ascending" : "descending"}`}
					className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md border border-input transition-colors hover:bg-muted"
					onClick={toggleSortDirection}
					type="button"
				>
					{isAscending ? (
						<IconSortAscending className="size-4" />
					) : (
						<IconSortDescending className="size-4" />
					)}
				</button>
			</div>
		</div>
	);
}

import { useDataExplorerContext } from "@adistack/data-explorer";
import { IconLineHeight } from "@tabler/icons-react";

import { cn } from "@/lib/utils";

const DENSITY_OPTIONS = [
	{ label: "Compact", value: "compact" },
	{ label: "Comfortable", value: "comfortable" },
	{ label: "Spacious", value: "spacious" },
] as const;

export function SpacingDensitySelector(): React.JSX.Element {
	const { table } = useDataExplorerContext();
	const density = table.state.density ?? "comfortable";

	return (
		<div className="p-3">
			<div className="mb-2 flex items-center gap-1.5 font-medium text-muted-foreground text-xs">
				<IconLineHeight className="size-3.5" />
				Density
			</div>
			<div className="flex gap-1">
				{DENSITY_OPTIONS.map((opt) => (
					<button
						className={cn(
							"flex-1 rounded-md border px-2 py-1 text-xs transition-colors",
							density === opt.value
								? "border-primary bg-primary/10 font-medium text-primary"
								: "border-input text-muted-foreground hover:bg-muted hover:text-foreground",
						)}
						key={opt.value}
						onClick={() => table.setDensity(opt.value)}
						type="button"
					>
						{opt.label}
					</button>
				))}
			</div>
		</div>
	);
}
